/// Cencora Phase 1: 10 pick + 12 putaway stations compile and have correct types.
#[test]
fn cencora_phase1_compiles_with_putaway_stations() {
    use std::collections::HashSet;

    let map = fixture_helpers::load_fixture("cencora_phase1");

    assert_eq!(map.stations.len(), 22, "22 stations (10 pick + 12 putaway)");

    let pick = map.stations_of_type(StationType::Pick);
    let putaway = map.stations_of_type(StationType::Putaway);
    assert_eq!(pick.len(), 10);
    assert_eq!(putaway.len(), 12);

    // All station IDs unique
    let ids: HashSet<_> = map.stations.iter().map(|s| s.id).collect();
    assert_eq!(ids.len(), 22);

    // All station position cells are StationArea
    for s in &map.stations {
        let cell = map.graph.cell(s.position).unwrap();
        assert_eq!(cell.kind, CellKind::StationArea, "station {} position", s.id.0);
    }

    // All presentation cells have neighbors (reachable)
    for s in &map.stations {
        let [point] = s.presentation_points.as_slice() else { panic!("station {} presents at one cell", s.id.0) };
        let nbrs = map.graph.neighbors(point.presentation_cell);
        assert!(!nbrs.is_empty(), "station {} presentation_cell unreachable", s.id.0);
    }
}

/// Dump edge traversability for every cell in the trivial_choreography map.
/// Run with `--nocapture` to see the output.
#[test]
fn trivial_choreography_edge_dump() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/trivial_choreography.json");
    let json = std::fs::read_to_string(&path).unwrap();
    let design: WarehouseDesign = serde_json::from_str(&json).unwrap();
    let map = design.compile().unwrap();

    let w = map.grid_bounds.unwrap().width;

    println!("Grid: {}x{}", w, map.grid_bounds.unwrap().depth);
    println!();

    // Print station info
    for s in &map.stations {
        let [point] = s.presentation_points.as_slice() else { panic!("station {} presents at one cell", s.id.0) };
        println!(
            "Station {}  position={:?}  presentation_cell={}  exit={:?}",
            s.id.0, s.position, point.presentation_cell.0, s.exit_direction,
        );
        for qc in &point.queue_path {
            println!("  queue cell {}", qc.0);
        }
    }
    println!();

    // Print relay info
    for r in &map.relays {
        println!("Relay  htm_access={}  vtm_access={}", r.htm_access.0, r.vtm_access.anchor().0);
    }
    println!();

    // Dump all cells and their outbound edges
    let mut cell_ids: Vec<u32> = map.graph.cells().map(|c| c.id.0).collect();
    cell_ids.sort();
    for id in cell_ids {
        let cid = CellId(id);
        let cell = map.graph.cell(cid).unwrap();
        let gp = cell.grid_pos.map(|g| format!("({},{})", g.x, g.y)).unwrap_or_else(|| "?".to_string());
        println!("Cell {:>3} {}  kind={:?}  zone={}", id, gp, cell.kind, cell.zone.0);
        for (tgt, edge) in map.graph.neighbors(cid) {
            let tgt_gp = map
                .graph
                .cell(tgt)
                .and_then(|c| c.grid_pos)
                .map(|g| format!("({},{})", g.x, g.y))
                .unwrap_or_else(|| "?".to_string());
            println!(
                "  -> {:>3} {}  htm={:?}  vtm={}  dest_only={:?}  vtm_zone_gate={:?}",
                tgt.0,
                tgt_gp,
                edge.traversability.htm_traversal,
                edge.traversability.vtm_traversal,
                edge.dest_only,
                edge.vtm_zone_gate,
            );
        }
    }
}

// -- cencora_v3 rack geometry --

/// The cencora A5 rack bay — the four-legged steel unit, tiled 6× per zone
/// side — rebuilt from the surveyed level tables. This is the committed
/// provenance for the fixture's `racks` entry (the original generation
/// script never made it into the repo). Bottom-left frame: x from the bay's
/// left leg, y from the floor. Board levels first (3 exchange positions at
/// 645 mm pitch, 425 mm margins), then 11 storage levels bottom-up (4 slots
/// per level at 500 mm pitch, 320 mm margins); the 2140 mm envelope closes
/// both series (320+3·500+320 = 425+2·645+425 = 2140), so tiled bays touch.
///
/// The rack is the bottom 13 of the drawings' beam levels: 2 board tiers +
/// 11 storage floors (top beam 7577 mm). HTMs exchange on board 0 only —
/// the sim's relay height is the board-0 floor and nothing consumes board 1
/// yet; it is carried for the two-lane relay work.
#[test]
fn cencora_v3_rack_prototype_matches_survey_tables() {
    use desmap::design::RackSlotDef;

    const BAY_LENGTH_MM: f64 = 2140.0;
    const BOARD_XS: [f64; 3] = [425.0, 1070.0, 1715.0];
    const BOARD_YS: [f64; 2] = [394.0, 952.0];
    const STORAGE_XS: [f64; 4] = [320.0, 820.0, 1320.0, 1820.0];
    const STORAGE_YS: [f64; 11] =
        [1580.0, 2138.0, 2697.0, 3461.0, 4020.0, 4578.0, 5137.0, 5696.0, 6460.0, 7018.0, 7577.0];

    let mut slots = Vec::new();
    for (board, &y) in BOARD_YS.iter().enumerate() {
        for &x in &BOARD_XS {
            slots.push(RackSlotDef { x, y, diving_board: true, diving_board_slot: Some(board as u32) });
        }
    }
    for &y in &STORAGE_YS {
        for &x in &STORAGE_XS {
            slots.push(RackSlotDef { x, y, diving_board: false, diving_board_slot: None });
        }
    }

    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/cencora_v3.json");
    let json = std::fs::read_to_string(&path).unwrap();
    let design: WarehouseDesign = serde_json::from_str(&json).unwrap();
    assert_eq!(design.racks.len(), 1);
    assert_eq!(design.racks[0].name, "cencora_a5_bay");
    assert_eq!(design.racks[0].length_mm, BAY_LENGTH_MM);
    assert_eq!(design.racks[0].slots, slots);

    // Each zone tiles the bay 6× per side, stepping by the envelope.
    for zone in design.zones.iter().filter_map(|z| match z {
        ZoneDef::Relay(rz) => Some(rz),
        _ => None,
    }) {
        assert_eq!(zone.rack_placements.len(), 12, "zone {}", zone.id);
        for (index, p) in zone.rack_placements.iter().enumerate() {
            assert_eq!(p.rack, "cencora_a5_bay");
            assert_eq!(p.x_offset_mm, (index % 6) as f64 * BAY_LENGTH_MM, "zone {} placement {}", zone.id, index);
        }
    }
}

/// Golden structure of the compiled cencora_v3 rack geometry. The spot
/// values are pinned from the pre-prototype compiled output (the inline-
/// slots form this fixture used to carry), so they also prove the
/// migration preserved the compiled contract.
#[test]
fn cencora_v3_compiled_slots_golden() {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/cencora_v3.json");
    let json = std::fs::read_to_string(&path).unwrap();
    let design: WarehouseDesign = serde_json::from_str(&json).unwrap();
    let map = design.compile().unwrap();

    let zones: Vec<_> = map.zones.iter().filter(|z| z.slots.is_some()).collect();
    assert_eq!(zones.len(), 19);

    // Zone 1 sits at origin [146, 20]; both rack columns carry the same
    // 300-slot run (Left col 146, Right col 148), length 18 → rows 20..37.
    let zone1 = zones.iter().find(|z| z.id.0 == 1).unwrap();
    let slots = zone1.slots.as_ref().unwrap();
    assert_eq!(slots.len(), 600);
    assert_eq!(slots.iter().filter(|s| s.diving_board).count(), 72);
    let s = &slots[0];
    assert_eq!((s.cell, s.x, s.y, s.diving_board, s.diving_board_slot), ([146, 20], 425.0, 394.0, true, Some(0)));
    let s = &slots[299];
    assert_eq!((s.cell, s.x, s.y, s.diving_board), ([146, 37], 12520.0, 7577.0, false));
    let s = &slots[300];
    assert_eq!((s.cell, s.x, s.y, s.diving_board, s.diving_board_slot), ([148, 20], 425.0, 394.0, true, Some(0)));
    let s = &slots[599];
    assert_eq!((s.cell, s.x, s.y, s.diving_board), ([148, 37], 12520.0, 7577.0, false));

    // Every zone materializes the same run, differing only by its origin:
    // equal modulo the per-zone [col, row] offset from zone 1.
    for zone in &zones {
        let other = zone.slots.as_ref().unwrap();
        assert_eq!(other.len(), 600, "zone {}", zone.id.0);
        let dc = other[0].cell[0] as i64 - slots[0].cell[0] as i64;
        let dr = other[0].cell[1] as i64 - slots[0].cell[1] as i64;
        for (a, b) in slots.iter().zip(other.iter()) {
            assert_eq!(b.cell[0] as i64 - a.cell[0] as i64, dc, "zone {}", zone.id.0);
            assert_eq!(b.cell[1] as i64 - a.cell[1] as i64, dr, "zone {}", zone.id.0);
            assert_eq!(
                (a.x, a.y, a.diving_board, a.diving_board_slot),
                (b.x, b.y, b.diving_board, b.diving_board_slot)
            );
        }
    }
}
